#!/usr/bin/env python3
"""Many-restart ViennaRNA inverse_fold on the canonical task target (from RNA_TASK_TARGET env)."""
import os, sys, multiprocessing as mp
import RNA

TARGET = os.environ["RNA_TASK_TARGET"].strip()
N = len(TARGET)

def run_fold(seed):
    # RNA.inverse_fold returns (sequence, distance). distance=0 means solved.
    md = RNA.md()
    md.dangles = 2
    md.temperature = 310.15  # 37C
    fc = RNA.fold_compound(TARGET, md)
    seq, dist = fc.inverse_fold("", TARGET)
    # verify
    if dist == 0:
        mfe, _ = fc.mfe()
        if mfe == TARGET:
            return (seed, seq, dist, True)
        return (seed, seq, dist, False)
    return (seed, seq, dist, False)

def main():
    nproc = min(64, os.cpu_count() or 32)
    restarts = 64
    with mp.Pool(nproc) as pool:
        results = pool.map(run_fold, list(range(restarts)))
    solved = []
    best = None
    bestd = 10**9
    for seed, seq, dist, exact in results:
        if dist < bestd:
            bestd = dist; best = seq
        if exact:
            solved.append(seq)
    print("target_len", N)
    print("n_solved", len(solved), "best_dist", bestd)
    if solved:
        print("SOLVED_SEQ:" + solved[0])
    else:
        print("BEST_SEQ:" + best)
        print("BEST_DIST", bestd)

if __name__ == "__main__":
    main()

