import os, sys, random, multiprocessing as mp
import RNA

TARGET = os.environ["RNA_TASK_TARGET"].strip()
N = len(TARGET)

def _setmd():
    md = RNA.md()
    md.dangles = 2
    md.temperature = 310.15
    RNA.cvar.dangles = 2
    return md

def run_fold(seed):
    rng = random.Random(seed)
    start = "".join(rng.choice("ACGU") for _ in range(N))
    try:
        seq, dist = RNA.inverse_fold(start, TARGET)
    except Exception as e:
        return (seed, "", 999, False, str(e))
    exact = False
    if dist == 0:
        fc = RNA.fold_compound(seq)
        mfe, _ = fc.mfe()
        if mfe == TARGET:
            exact = True
    return (seed, seq, dist, exact, "")

def init():
    _setmd()

def main():
    nproc = min(80, os.cpu_count() or 32)
    restarts = 80
    with mp.Pool(nproc, initializer=init) as pool:
        results = pool.map(run_fold, list(range(restarts)))
